import{j as e}from"./blog-pages-Cba4hDr6.js";import{I as a}from"./I18nErpPage-ZycbTUcF.js";import"./PillarHubNav-DYiypIRQ.js";import"./badge-CKYDyVwk.js";const o={heroBadge:"Sistema de gestión de inspección END",heroTitle:"Software ERP de Ensayos No Destructivos en Bogotá",heroSubtitle:"Sistema integral de gestión de inspección",heroIntro:"ERP especializado para empresas de Ensayos No Destructivos que operan en Bogotá y atienden a Ecopetrol y los principales operadores colombianos. Automatice el seguimiento de certificaciones ASNT, ICONTEC y la programación API.",ctaPrimary:"Solicitar demostración para Bogotá",ctaSecondary:"English version",statCompanies:"Empresas END usando Atlantis ERP",statRating:"Calificación promedio de clientes",statAdminReduction:"Reducción en tiempo administrativo",statModules:"Módulos centrales para END",marketContextLabel:"Contexto del mercado END",painPointsTitle:"Por qué los equipos END en Bogotá eligen Atlantis ERP",painPointsSubtitle:"Tres puntos críticos de operación eliminados desde el día uno",problemLabel:"El problema",solutionLabel:"La solución",modulesTitle:"Seis módulos centrales para empresas de inspección END",modulesSubtitle:"Cada módulo está diseñado específicamente para la industria de inspección",roiTitle:"ROI de Atlantis ERP en Bogotá",faqTitle:"Preguntas frecuentes — Atlantis NDT ERP en Bogotá",alsoServingTitle:"También servimos",finalCtaTitle:"¿Listo para modernizar sus operaciones END en Bogotá?",finalCtaBody:"Únase a las empresas de inspección que sirven a Ecopetrol en Barrancabermeja, Cartagena y los Llanos Orientales que han modernizado sus operaciones con Atlantis NDT ERP.",finalCtaPrimary:"Solicitar demostración",finalCtaSecondary:"View English version",switchLangLabel:"English version"};function t(){return e.jsx(a,{lang:"es",dir:"ltr",city:"Bogotá",countryCode:"CO",countryName:"Colombia",slug:"ndt-erp-bogota",canonicalPath:"/es/ndt-erp-bogota",englishPath:"/ndt-erp-bogota",pageTitle:"Software ERP END en Bogotá | Gestión de Inspección Industrial Colombia | Atlantis NDT",pageDescription:"Software ERP de Ensayos No Destructivos para empresas de inspección en Bogotá, Colombia. Seguimiento de certificaciones ASNT, ICONTEC, programación API 510/570/653 y reportes Ecopetrol.",keywords:"software END Bogotá, ERP Colombia, ASNT, ICONTEC, API 510, Ecopetrol, Barrancabermeja, Cartagena refinería, ANH",marketContext:"Bogotá funciona como el centro administrativo y financiero de la industria colombiana de hidrocarburos, hogar de las oficinas centrales de Ecopetrol, Cenit, Geopark y las principales empresas de inspección que dan servicio a la refinería de Barrancabermeja, la refinería de Cartagena, los campos de los Llanos Orientales y el creciente sector de gas natural en La Guajira. Las empresas de Ensayos No Destructivos colombianas que operan desde Bogotá deben gestionar las certificaciones ASNT SNT-TC-1A e ISO 9712, las normas técnicas del Instituto Colombiano de Normas Técnicas y Certificación (ICONTEC), además del cumplimiento con las resoluciones de la Agencia Nacional de Hidrocarburos (ANH) y los requisitos específicos de Ecopetrol Downstream para inspección de refinerías. Atlantis NDT ERP proporciona a los equipos de inspección en Bogotá una plataforma unificada para el seguimiento integrado de certificaciones ASNT y calificaciones específicas de Ecopetrol, la programación automatizada de inspecciones según API 510 para recipientes a presión, API 570 para tubería y API 653 para tanques, y la generación de reportes PDF en español compatibles con los estándares internos de Ecopetrol Refinería de Cartagena (Reficar) y los requisitos de la Superintendencia de Industria y Comercio. El sistema también soporta la operación distribuida típica colombiana, con técnicos rotando entre Bogotá y los campos productores en los departamentos de Casanare, Meta y Putumayo.",roiBody:"Los clientes de Atlantis NDT ERP en Bogotá reportan una reducción del 40% en tiempo administrativo durante los primeros seis meses, con el tiempo de elaboración de un reporte API 510 reducido de cuatro horas a menos de cinco minutos. Las alertas automáticas eliminan los incidentes de caducidad de certificaciones ASNT en equipos rotativos que trabajan en los Llanos Orientales, y la preparación de paquetes de auditoría para revisiones de Ecopetrol y la ANH pasa de varios días a un solo clic. Para un equipo de inspección de diez técnicos que da servicio a refinerías y campos productores colombianos, esto representa un ahorro anual estimado entre 60 y 85 millones de pesos colombianos en sobrecarga administrativa recuperable, además del valor preventivo de evitar la pérdida de habilitación como contratista de Ecopetrol.",painPoints:[{title:"Operaciones distribuidas en campos remotos",problem:"Los técnicos de inspección que rotan entre Bogotá y los campos de los Llanos Orientales (Casanare, Meta) o el Putumayo enfrentan desafíos logísticos para mantener actualizados los registros de certificación y datos de inspección con conectividad limitada en zonas remotas.",solution:"Atlantis ERP funciona offline en campos remotos como Rubiales, Castilla y Caño Limón, sincronizando automáticamente al regresar a Bogotá o a las bases de Yopal y Villavicencio, con paneles que rastrean asignaciones por proyecto."},{title:"Reportes manuales para Ecopetrol",problem:"Los equipos de inspección en Bogotá invierten horas reformateando reportes API al formato interno requerido por Ecopetrol Downstream para inspecciones en las refinerías de Barrancabermeja y Cartagena (Reficar).",solution:"Genere un reporte completo en formato Ecopetrol con su logotipo corporativo y firma digital en menos de cinco minutos directamente desde los datos capturados en campo, eliminando los errores de copia y el tiempo perdido en reformateo."},{title:"Auditorías de la ANH y Ecopetrol",problem:"Las auditorías periódicas de la ANH y de Ecopetrol detectan frecuentemente empresas de inspección en Bogotá sin registros organizados de calificaciones del personal e historial de inspección, comprometiendo la habilitación como contratista.",solution:"Atlantis ERP genera un paquete completo de auditoría con un solo clic en cualquier momento, incluyendo historial de inspección de activos, registros de calificación del personal, certificados de calibración y reportes de cumplimiento."}],modules:[{title:"Programación de inspección y órdenes de trabajo",description:"Automatice el cálculo de intervalos según API 510, API 570, API 653 y los intervalos RBI requeridos por Ecopetrol. Asigne técnicos a campos en los Llanos y Putumayo en segundos.",features:["Cálculo automático de intervalos API","Programación RBI","Matriz de disponibilidad de técnicos rotativos","Flujos de aprobación Ecopetrol","Acceso móvil offline en Llanos Orientales"]},{title:"Seguimiento de certificaciones del personal",description:"Centralice registros de certificaciones ASNT SNT-TC-1A, ISO 9712, ICONTEC y calificaciones específicas de Ecopetrol y operadores colombianos.",features:["Alertas de vencimiento ASNT","Seguimiento ISO 9712 y ICONTEC","Matriz de calificaciones Ecopetrol","Recordatorios automáticos de renovación","Exportación PDF para auditoría"]},{title:"Generación de reportes de inspección",description:"Genere reportes profesionales según API 510, API 570, API 653, ASME Sección VIII y formatos específicos de Ecopetrol Refinería y Reficar.",features:["Plantillas API 510","Formatos API 570","Reportes API 653","Constructor de plantillas Ecopetrol","Integración de firma digital"]},{title:"Gestión de datos de corrosión",description:"Registre mediciones de espesor y cálculos de vida remanente para activos de Ecopetrol en Barrancabermeja, Cartagena y campos productores de los Llanos.",features:["Base de datos de mediciones","Gráficos de tendencia de corrosión","Cálculo de vida remanente","Alertas de pérdida de pared","Exportación API 579"]},{title:"Registro de activos y equipos",description:"Mantenga un registro digital completo de activos en refinerías y campos productores. Rastree calibraciones según los requisitos del Organismo Nacional de Acreditación de Colombia (ONAC).",features:["Jerarquía de activos P&ID","Calibraciones ONAC","Etiquetado QR de activos","Historial de inspección por activo","Clasificación de riesgo"]},{title:"Tablero de cumplimiento",description:"Visibilidad en tiempo real del cumplimiento con resoluciones de la ANH y normativas de Ecopetrol y Cenit.",features:["Alertas de inspecciones vencidas","Vista multi-cliente","KPIs de cumplimiento","Alertas de cambios regulatorios","Reportes ejecutivos"]}],integrations:["Formatos de reporte Ecopetrol Refinería","Certificaciones ICONTEC","Calibración ONAC","Reportes Agencia Nacional de Hidrocarburos (ANH)","Integración SAP S/4HANA PM","Formatos Cenit para transporte de hidrocarburos","Cumplimiento Superintendencia de Industria y Comercio","Soporte rotacional para operaciones en Llanos Orientales"],faqs:[{question:"¿El sistema soporta operaciones en los Llanos Orientales?",answer:"Sí. Atlantis ERP incluye soporte específico para operaciones rotativas en los campos productores de Casanare, Meta y Putumayo, con captura de datos sin conexión en campos como Rubiales, Castilla, Caño Limón y Quifa. El sistema sincroniza automáticamente al regresar a las bases de Yopal y Villavicencio o a Bogotá, y rastrea las asignaciones rotacionales típicas de la industria colombiana."},{question:"¿Cómo se integra el sistema con los requisitos de Ecopetrol?",answer:"El sistema incluye plantillas pre-aprobadas para los formatos de reporte requeridos por Ecopetrol Refinería de Barrancabermeja, Reficar (Refinería de Cartagena) y Cenit para inspección de oleoductos y poliductos. Las plantillas se actualizan automáticamente cuando Ecopetrol emite nuevas versiones de sus requisitos internos, garantizando que su empresa mantenga la habilitación como contratista."},{question:"¿El sistema cumple con las certificaciones ICONTEC?",answer:"Sí. El módulo de personal soporta el registro completo de certificaciones según las normas técnicas colombianas emitidas por ICONTEC, con campos específicos para los métodos calificados, fechas de vigencia y referencias a los exámenes. El sistema mantiene archivos digitales de los certificados ICONTEC listos para presentación en auditorías de clientes y autoridades regulatorias."},{question:"¿Se pueden generar reportes en español para entes regulatorios colombianos?",answer:"Sí. El sistema genera todos los reportes en español por defecto, con la opción de incluir secciones bilingües español-inglés para clientes corporativos internacionales como Geopark, Frontera Energy o las empresas con casa matriz fuera de Colombia. Los reportes cumplen con los formatos requeridos por la Superintendencia de Industria y Comercio y la Agencia Nacional de Hidrocarburos."},{question:"¿Cuál es el tiempo de implementación para una empresa de inspección en Bogotá?",answer:"El tiempo típico de implementación es de cuatro a seis semanas, incluyendo la migración de datos históricos desde hojas de cálculo, capacitación de los equipos en español y la integración de las plantillas de reporte específicas de Ecopetrol, Cenit y otros clientes. Nuestro equipo ofrece capacitación virtual y, para empresas más grandes, capacitación presencial en Bogotá para garantizar una adopción rápida."}],ui:o})}export{t as default};
